def solve(values):
    def rotate_word(word):
        shift = 13
        word = word[::-1]  # Reverse to make rotation easier
        new_word = ''
        for i in range(len(word)):
            new_char = chr(ord(word[i]) + shift)
            if new_char > 'z':
                new_char = chr(ord(new_char) - 26)
            new_word += new_char
        new_word = new_word[::-1]  # Reverse back
        return new_word

    return ' '.join([rotate_word(w) for w in values])
```

